ctx.fillStyle='#152629';ctx.fillRect(85,540,world.w-170,80);ctx.fillRect(820,90,75,world.h-180);ctx.fillRect(1380,90,68,world.h-180);ctx.strokeStyle='#425b55';ctx.setLineDash([22,22]);ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(100,580);ctx.lineTo(world.w-95,580);ctx.moveTo(855,105);ctx.lineTo(855,world.h-100);ctx.moveTo(1414,100);ctx.lineTo(1414,world.h-100);ctx.stroke();ctx.setLineDash([]);
for(const d of decor){ctx.fillStyle=d.type>.5?'#182b2b':'#24302b';ctx.globalAlpha=.6;ctx.beginPath();ctx.arc(d.x,d.y,d.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}
